import React from "react";

class FAQ extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      openFaq: 0,
    };
  }

  handleFaq = (index) => {
    this.setState((prevState) => ({
      openFaq:
        prevState.openFaq === index ? null : index,
    }));
  };

  render() {
    const { openFaq } = this.state;

    const faqs = [
      {
        question: "این درمان چقدر طول می‌کشد؟",
        answer:
          "معمولاً بین ۶۰ تا ۷۵ دقیقه، بسته به نوع پوست و نیاز شما.",
      },
      {
        question: "آیا این درمان درد دارد؟",
        answer:
          "خیر، هیدرافیشیال یک روش کاملاً بدون درد و بدون نیاز به دوره نقاهت است.",
      },
      {
        question: "هر چند وقت یک‌بار باید انجامش بدهم؟",
        answer:
          "برای بهترین نتیجه، هر ۴ تا ۶ هفته یک‌بار توصیه می‌شود.",
      },
    ];

    return (
      <>
        <h3 className="detail-h2">
          سوالات متداول
        </h3>

        <div className="faq-list">
          {faqs.map((faq, index) => (
            <div
              className={`faq-item ${
                openFaq === index ? "open" : ""
              }`}
              key={index}
            >
              <button
                className="faq-q"
                onClick={() => this.handleFaq(index)}
              >
                {faq.question}

                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="m6 9 6 6 6-6" />
                </svg>
              </button>

              {openFaq === index && (
                <div className="faq-a">
                  <div className="faq-a-in">
                    {faq.answer}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </>
    );
  }
}

export default FAQ;
